void SAL_CALL FragmentHandler2::endFastElement( sal_Int32 nElement )
{
    /* If MCE */
    switch( nElement )
    {
        case MCE_TOKEN( AlternateContent ):
            removeMCEState();
            break;
    }

    implEndElement( nElement );
}
